  'main-heading' => 'PDF vs DOCX. Ֆայլի ո՞ր ձևաչափը պետք է օգտագործեք և երբ:',
  'intro-heading' => 'Որոշում, որը շատերն ընդունում են առանց մտածելու',
  'intro-para1' => 'Ամեն օր միլիոնավոր մարդիկ կտտացնում են Save As-ը և ընտրում PDF-ի և DOCX-ի միջև՝ առանց ընդհատելու՝ մտածելու, թե որն է իրականում ծառայում իրենց նպատակին: Շատ փաստաթղթերի համար ընտրությունը մեծ նշանակություն ունի: Սխալ ձևաչափ ուղարկելը կարող է նշանակել, որ ստացողը չի կարող բացել ձեր ֆայլը, չի կարող խմբագրել փաստաթուղթը, որը պետք է փոփոխի, կամ ստանում է մի բան, որն իր սարքում բոլորովին այլ տեսք ունի, քան ձերը:',
  'intro-para2' => 'Այս երկու ձևաչափերի միջև տարբերությունը հասկանալը տևում է մոտ հինգ րոպե, և այն ընդմիշտ լուծում է երկիմաստությունը: Այս ուղեցույցը բացատրում է, թե ինչ է նախատեսված յուրաքանչյուր ձևաչափի համար, ինչ իրավիճակներ են պահանջում յուրաքանչյուրը և ինչպես անհրաժեշտության դեպքում փոխարկել դրանց միջև:',
  'pdf-built-heading' => 'Ինչի համար է ստեղծվել PDF-ը',
  'pdf-built-para1' => 'PDF-ը նշանակում է դյուրակիր փաստաթղթի ձևաչափ: Adobe-ն այն ստեղծել է 1993 թվականին՝ մեկ հստակ նպատակով. փաստաթուղթը դարձնել նույն տեսքը յուրաքանչյուր սարքի, օպերացիոն համակարգի և էկրանի վրա, որի վրա այն բացվում է: PDF-ն հասնում է դրան՝ կոդավորելով փաստաթղթի ամբողջական տեսողական ներկայացումը ինքնուրույն ֆայլի մեջ: Տառատեսակի բոլոր տվյալները, պատկերի տվյալները, դասավորության չափումները և գունային տեղեկատվությունը տարածվում են ֆայլի հետ:',
